DROP TABLE IF EXISTS `md_period`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_period` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `company_id` bigint NOT NULL COMMENT '公司ID',
  `period_year` int NOT NULL COMMENT '会计年度',
  `period_month` int NOT NULL COMMENT '会计月份 1-12',
  `begin_date` date NOT NULL COMMENT '期间起始日',
  `end_date` date NOT NULL COMMENT '期间结束日',
  `status` varchar(20) NOT NULL DEFAULT 'OPEN' COMMENT '状态:OPEN已开启/CLOSING关账中/CLOSED已关账',
  `close_time` datetime DEFAULT NULL COMMENT '关账时间',
  `close_by` bigint DEFAULT NULL COMMENT '关账人',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_period` (`tenant_id`,`company_id`,`period_year`,`period_month`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=226 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会计期间';
